import json
import sys
import re

def validate_expenses(expenses):
    required_keys = {'title', 'date', 'items'}
    for key in required_keys:
        if key not in expenses:
            print(f"Missing key: {key}", file=sys.stderr)
            sys.exit(1)

    for item in expenses['items']:
        item_keys = {'name', 'quantity', 'unit_price'}
        for key in item_keys:
            if key not in item:
                print(f"Missing key: {key}", file=sys.stderr)
                sys.exit(1)

def generate_items_html(items):
    html_rows = []
    for item in items:
        line_total = round(item['quantity'] * item['unit_price'], 2)
        row = (
            f"<tr><td>{item['name']}</td>"
            f"<td>{int(item['quantity'])}</td>"
            f"<td>{item['unit_price']:.2f}</td>"
            f"<td>{line_total:.2f}</td></tr>"
        )
        html_rows.append(row)
    return ''.join(html_rows)

def replace_placeholders(template, title, date, items_html):
    def replacer(match):
        placeholder = match.group(0)
        if placeholder == '{{title}}':
            return title
        elif placeholder == '{{date}}':
            return date
        elif placeholder == '{{items}}':
            return items_html
        return match.group(0)

    return re.sub(r'\{\{.*?\}\}', replacer, template)

def main():
    if len(sys.argv) != 4:
        print("Usage: python expense_report.py expenses.json report_template.html report.html", file=sys.stderr)
        sys.exit(1)

    expenses_file = sys.argv[1]
    template_file = sys.argv[2]
    output_file = sys.argv[3]

    try:
        with open(expenses_file, 'r') as f:
            expenses = json.load(f)
    except json.JSONDecodeError:
        print("Invalid JSON in expenses file", file=sys.stderr)
        sys.exit(1)

    validate_expenses(expenses)

    try:
        with open(template_file, 'r') as f:
            template = f.read()
    except IOError:
        print(f"Could not read template file: {template_file}", file=sys.stderr)
        sys.exit(1)

    items_html = generate_items_html(expenses['items'])
    processed_template = replace_placeholders(template, expenses['title'], expenses['date'], items_html)

    try:
        with open(output_file, 'w') as f:
            f.write(processed_template)
    except IOError:
        print(f"Could not write to output file: {output_file}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

